#include <iiMultimodalAgent/agent/Api.h>
#include <HttpApiServer.h>
#include <LocalIpcServer.h>

auto registry = std::make_shared<iiMultimodalAgent::agent::ToolRegistry>();
iiMultimodalAgent::agent::registerWorkspaceTools(*registry, workspace);
iiMultimodalAgent::agent::ApiOptions options;
options.workingDirectory = workspace;
options.stateDirectory = privateState;
options.clientTokens = {{"society", societyToken}, {"dreamscapes", dreamscapesToken}};
auto api = std::make_shared<iiMultimodalAgent::agent::Api>(
    std::make_shared<iiMultimodalAgent::agent::ServiceModel>(service), registry, policy, options);
iiLocalLLM::LocalIpcServer ipc(service);
iiLocalLLM::HttpApiServer http(service);
ipc.setRpcHandler(api);
http.setRpcHandler(api);
// 이후 listen(). 호스트 종료 순서는 두 전송 close(), api->close(), Service 정리.
